def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([7]), fmt([-7]), fmt([0]), fmt([5, 5, 5]), fmt([-1, -2, -3]), fmt([10**9, -10**9]),
             fmt([-10**9, -10**9]), fmt([1, 2, 3, 4, 5]), fmt([5, 4, 3, 2, 1])]
    for n in (2, 3, 5, 8, 12, 20, 30):
        for _ in range(2):
            tests.append(fmt([rng.randint(-50, 50) for _ in range(n)]))
    for _ in range(3):
        tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(rng.randint(20, 30))]))
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(100000)]))
    tests.append(fmt([rng.randint(-10**9, -10**9 + 5) for _ in range(100000)]))
    tests.append(fmt(list(range(100000))))
    return tests

